1	import { Router } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  AGENT_ADAPTER_TYPES,
5	  createEnvironmentSchema,
6	  getEnvironmentCapabilities,
7	  probeEnvironmentConfigSchema,
8	  updateEnvironmentSchema,
9	} from "@paperclipai/shared";
10	import { forbidden } from "../errors.js";
11	import { validate } from "../middleware/validate.js";
12	import {
13	  accessService,
14	  agentService,
15	  issueService,
16	  logActivity,
17	  projectService,
18	} from "../services/index.js";
19	import {
20	  normalizeEnvironmentConfigForPersistence,
21	  normalizeEnvironmentConfigForProbe,
22	  parseEnvironmentDriverConfig,
23	  readSshEnvironmentPrivateKeySecretId,
24	  type ParsedEnvironmentConfig,
25	} from "../services/environment-config.js";
26	import { probeEnvironment } from "../services/environment-probe.js";
27	import { secretService } from "../services/secrets.js";
28	import { listReadyPluginEnvironmentDrivers } from "../services/plugin-environment-driver.js";
29	import { assertCompanyAccess, getActorInfo } from "./authz.js";
30	import type { PluginWorkerManager } from "../services/plugin-worker-manager.js";
31	import { environmentService } from "../services/environments.js";
32	import { executionWorkspaceService } from "../services/execution-workspaces.js";
33	import { expressHandler } from "../http/express-adapter.js";
34	import type { Handler, RequestCtx } from "../http/types.js";
35	import type { StorageService } from "../storage/types.js";
36	
37	export function environmentRoutes(
38	  db: Db,
39	  options: { pluginWorkerManager?: PluginWorkerManager } = {},
40	) {
41	  const router = Router();
42	  const agents = agentService(db);
43	  const access = accessService(db);
44	  const svc = environmentService(db);
45	  const executionWorkspaces = executionWorkspaceService(db);
46	  const issues = issueService(db);
47	  const projects = projectService(db);
48	  const secrets = secretService(db);
49	
50	  // Storage is not needed by any environment handler; supply a sentinel that
51	  // throws if accidentally accessed, keeping the adapter type contract honest.
52	  const storageSentinel = new Proxy({} as StorageService, {
53	    get(_target, prop) {
54	      throw new Error(`environment handler unexpectedly accessed storage.${String(prop)}`);
55	    },
56	  });
57	
58	  function parseObject(value: unknown): Record<string, unknown> {
59	    return value && typeof value === "object" && !Array.isArray(value)
60	      ? (value as Record<string, unknown>)
61	      : {};
62	  }
63	
64	  function canCreateAgents(agent: { permissions: Record<string, unknown> | null | undefined }) {
65	    if (!agent.permissions || typeof agent.permissions !== "object") return false;
66	    return Boolean((agent.permissions as Record<string, unknown>).canCreateAgents);
67	  }
68	
69	  // ---------------------------------------------------------------------------
70	  // Internal authz helpers operating on RequestCtx (not Express Request)
71	  // ---------------------------------------------------------------------------
72	
73	  async function assertCanMutateEnvironments(ctx: RequestCtx, companyId: string) {
74	    // ctx.actor is null when type was "none"; express-adapter normalises that.
75	    if (!ctx.actor) throw forbidden("Authentication required");
76	    const actor = ctx.actor;
77	
78	    if (actor.type === "board") {
79	      // We only have the minimal ActorContext here (no source/isInstanceAdmin/
80	      // companyIds). Rely on the per-company access service instead.
81	      const allowed = await access.canUser(companyId, actor.userId ?? "", "environments:manage");
82	      if (!allowed) {
83	        throw forbidden("Missing permission: environments:manage");
84	      }
85	      return;
86	    }
87	
88	    if (!actor.agentId) {
89	      throw forbidden("Agent authentication required");
90	    }
91	
92	    const actorAgent = await agents.getById(actor.agentId);
93	    if (!actorAgent || actorAgent.companyId !== companyId) {
94	      throw forbidden("Agent key cannot access another company");
95	    }
96	
97	    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "environments:manage");
98	    if (allowedByGrant || canCreateAgents(actorAgent)) {
99	      return;
100	    }
101	
102	    throw forbidden("Missing permission: environments:manage");
103	  }
104	
105	  async function actorCanReadEnvironmentConfigurations(ctx: RequestCtx, companyId: string) {
106	    if (!ctx.actor) return false;
107	    const actor = ctx.actor;
108	
109	    if (actor.type === "board") {
110	      return access.canUser(companyId, actor.userId ?? "", "environments:manage");
111	    }
112	
113	    if (!actor.agentId) return false;
114	    const actorAgent = await agents.getById(actor.agentId);
115	    if (!actorAgent || actorAgent.companyId !== companyId) return false;
116	    const allowedByGrant = await access.hasPermission(companyId, "agent", actorAgent.id, "environments:manage");
117	    return allowedByGrant || canCreateAgents(actorAgent);
118	  }
119	
120	  function redactEnvironmentForRestrictedView<T extends {
121	    config: Record<string, unknown>;
122	    metadata: Record<string, unknown> | null;
123	  }>(environment: T): T & { configRedacted: true; metadataRedacted: true } {
124	    return {
125	      ...environment,
126	      config: {},
127	      metadata: null,
128	      configRedacted: true,
129	      metadataRedacted: true,
130	    };
131	  }
132	
133	  function summarizeEnvironmentUpdate(
134	    patch: Record<string, unknown>,
135	    environment: {
136	      name: string;
137	      driver: string;
138	      status: string;
139	    },
140	  ): Record<string, unknown> {
141	    const details: Record<string, unknown> = {
142	      changedFields: Object.keys(patch).sort(),
143	    };
144	
145	    if (patch.name !== undefined) details.name = environment.name;
146	    if (patch.driver !== undefined) details.driver = environment.driver;
147	    if (patch.status !== undefined) details.status = environment.status;
148	    if (patch.description !== undefined) details.descriptionChanged = true;
149	    if (patch.config !== undefined) {
150	      details.configChanged = true;
151	      details.configTopLevelKeyCount =
152	        patch.config && typeof patch.config === "object" && !Array.isArray(patch.config)
153	          ? Object.keys(patch.config as Record<string, unknown>).length
154	          : 0;
155	    }
156	    if (patch.metadata !== undefined) {
157	      details.metadataChanged = true;
158	      details.metadataTopLevelKeyCount =
159	        patch.metadata && typeof patch.metadata === "object" && !Array.isArray(patch.metadata)
160	          ? Object.keys(patch.metadata as Record<string, unknown>).length
161	          : 0;
162	    }
163	
164	    return details;
165	  }
166	
167	  // Helper to derive actorInfo-equivalent from RequestCtx
168	  function ctxActorInfo(ctx: RequestCtx) {
169	    const actor = ctx.actor;
170	    if (!actor) throw forbidden("Authentication required");
171	    if (actor.type === "agent") {
172	      return {
173	        actorType: "agent" as const,
174	        actorId: actor.agentId ?? "unknown-agent",
175	        agentId: actor.agentId ?? null,
176	        runId: null as string | null,
177	      };
178	    }
179	    return {
180	      actorType: "user" as const,
181	      actorId: actor.userId ?? "board",
182	      agentId: null as string | null,
183	      runId: null as string | null,
184	    };
185	  }
186	
187	  // ---------------------------------------------------------------------------
188	  // Handlers
189	  // ---------------------------------------------------------------------------
190	
191	  const listEnvironments: Handler = async (ctx) => {
192	    const companyId = ctx.param("companyId");
193	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
194	    if (!ctx.actor) throw forbidden("Authentication required");
195	    const rows = await svc.list(companyId, {
196	      status: ctx.query("status"),
197	      driver: ctx.query("driver"),
198	    });
199	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(ctx, companyId);
200	    if (canReadConfigs) {
201	      return Response.json(rows);
202	    }
203	    return Response.json(rows.map((environment) => redactEnvironmentForRestrictedView(environment)));
204	  };
205	
206	  const getEnvironmentCapabilitiesHandler: Handler = async (ctx) => {
207	    const companyId = ctx.param("companyId");
208	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
209	    if (!ctx.actor) throw forbidden("Authentication required");
210	    const pluginDrivers = await listReadyPluginEnvironmentDrivers({
211	      db,
212	      workerManager: options.pluginWorkerManager,
213	    });
214	    return Response.json(getEnvironmentCapabilities(
215	      AGENT_ADAPTER_TYPES,
216	      {
217	        sandboxProviders: Object.fromEntries(pluginDrivers.map((driver) => [
218	          driver.driverKey,
219	          {
220	            status: "supported" as const,
221	            supportsSavedProbe: true,
222	            supportsUnsavedProbe: true,
223	            supportsRunExecution: true,
224	            supportsReusableLeases: true,
225	            displayName: driver.displayName,
226	            description: driver.description,
227	            source: "plugin" as const,
228	            pluginKey: driver.pluginKey,
229	            pluginId: driver.pluginId,
230	            configSchema: driver.configSchema,
231	          },
232	        ])),
233	      },
234	    ));
235	  };
236	
237	  const createEnvironment: Handler = async (ctx) => {
238	    const companyId = ctx.param("companyId");
239	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
240	    await assertCanMutateEnvironments(ctx, companyId);
241	    const actor = ctxActorInfo(ctx);
242	    const body = await ctx.json<Record<string, unknown>>();
243	    const input = {
244	      ...body,
245	      config: await normalizeEnvironmentConfigForPersistence({
246	        db,
247	        companyId,
248	        environmentName: body.name as string,
249	        driver: body.driver as string,
250	        config: body.config,
251	        actor: {
252	          agentId: actor.agentId,
253	          userId: actor.actorType === "user" ? actor.actorId : null,
254	        },
255	        pluginWorkerManager: options.pluginWorkerManager,
256	      }),
257	    };
258	    const environment = await svc.create(companyId, input);
259	    await logActivity(db, {
260	      companyId,
261	      actorType: actor.actorType,
262	      actorId: actor.actorId,
263	      agentId: actor.agentId,
264	      runId: actor.runId,
265	      action: "environment.created",
266	      entityType: "environment",
267	      entityId: environment.id,
268	      details: {
269	        name: environment.name,
270	        driver: environment.driver,
271	        status: environment.status,
272	      },
273	    });
274	    return Response.json(environment, { status: 201 });
275	  };
276	
277	  const getEnvironment: Handler = async (ctx) => {
278	    const id = ctx.param("id");
279	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
280	    const environment = await svc.getById(id);
281	    if (!environment) {
282	      return Response.json({ error: "Environment not found" }, { status: 404 });
283	    }
284	    if (!ctx.actor) throw forbidden("Authentication required");
285	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(ctx, environment.companyId);
286	    if (canReadConfigs) {
287	      return Response.json(environment);
288	    }
289	    return Response.json(redactEnvironmentForRestrictedView(environment));
290	  };
291	
292	  const listEnvironmentLeases: Handler = async (ctx) => {
293	    const id = ctx.param("id");
294	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
295	    const environment = await svc.getById(id);
296	    if (!environment) {
297	      return Response.json({ error: "Environment not found" }, { status: 404 });
298	    }
299	    if (!ctx.actor) throw forbidden("Authentication required");
300	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(ctx, environment.companyId);
301	    if (!canReadConfigs) {
302	      throw forbidden("Missing permission: environments:manage");
303	    }
304	    const leases = await svc.listLeases(environment.id, {
305	      status: ctx.query("status"),
306	    });
307	    return Response.json(leases);
308	  };
309	
310	  const getEnvironmentLease: Handler = async (ctx) => {
311	    const leaseId = ctx.param("leaseId");
312	    if (!leaseId) return Response.json({ error: "Missing leaseId" }, { status: 400 });
313	    const lease = await svc.getLeaseById(leaseId);
314	    if (!lease) {
315	      return Response.json({ error: "Environment lease not found" }, { status: 404 });
316	    }
317	    if (!ctx.actor) throw forbidden("Authentication required");
318	    const canReadConfigs = await actorCanReadEnvironmentConfigurations(ctx, lease.companyId);
319	    if (!canReadConfigs) {
320	      throw forbidden("Missing permission: environments:manage");
321	    }
322	    return Response.json(lease);
323	  };
324	
325	  const updateEnvironment: Handler = async (ctx) => {
326	    const id = ctx.param("id");
327	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
328	    const existing = await svc.getById(id);
329	    if (!existing) {
330	      return Response.json({ error: "Environment not found" }, { status: 404 });
331	    }
332	    await assertCanMutateEnvironments(ctx, existing.companyId);
333	    const actor = ctxActorInfo(ctx);
334	    const body = await ctx.json<Record<string, unknown>>();
335	    const nextDriver = (body.driver as string | undefined) ?? existing.driver;
336	    const nextName = (body.name as string | undefined) ?? existing.name;
337	    const configSource =
338	      body.config !== undefined
339	        ? body.driver !== undefined && body.driver !== existing.driver
340	          ? body.config
341	          : {
342	              ...parseObject(existing.config),
343	              ...parseObject(body.config),
344	            }
345	        : body.driver !== undefined && body.driver !== existing.driver
346	          ? {}
347	          : existing.config;
348	    const patch = {
349	      ...body,
350	      ...(body.config !== undefined || body.driver !== undefined
351	        ? {
352	            config: await normalizeEnvironmentConfigForPersistence({
353	              db,
354	              companyId: existing.companyId,
355	              environmentName: nextName,
356	              driver: nextDriver,
357	              config: configSource,
358	              actor: {
359	                agentId: actor.agentId,
360	                userId: actor.actorType === "user" ? actor.actorId : null,
361	              },
362	              pluginWorkerManager: options.pluginWorkerManager,
363	            }),
364	          }
365	        : {}),
366	    };
367	    const environment = await svc.update(existing.id, patch);
368	    if (!environment) {
369	      return Response.json({ error: "Environment not found" }, { status: 404 });
370	    }
371	    await logActivity(db, {
372	      companyId: environment.companyId,
373	      actorType: actor.actorType,
374	      actorId: actor.actorId,
375	      agentId: actor.agentId,
376	      runId: actor.runId,
377	      action: "environment.updated",
378	      entityType: "environment",
379	      entityId: environment.id,
380	      details: summarizeEnvironmentUpdate(patch as Record<string, unknown>, environment),
381	    });
382	    return Response.json(environment);
383	  };
384	
385	  const deleteEnvironment: Handler = async (ctx) => {
386	    const id = ctx.param("id");
387	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
388	    const existing = await svc.getById(id);
389	    if (!existing) {
390	      return Response.json({ error: "Environment not found" }, { status: 404 });
391	    }
392	    await assertCanMutateEnvironments(ctx, existing.companyId);
393	    await Promise.all([
394	      executionWorkspaces.clearEnvironmentSelection(existing.companyId, existing.id),
395	      issues.clearExecutionWorkspaceEnvironmentSelection(existing.companyId, existing.id),
396	      projects.clearExecutionWorkspaceEnvironmentSelection(existing.companyId, existing.id),
397	    ]);
398	    const removed = await svc.remove(existing.id);
399	    if (!removed) {
400	      return Response.json({ error: "Environment not found" }, { status: 404 });
401	    }
402	    const secretId = readSshEnvironmentPrivateKeySecretId(existing);
403	    if (secretId) {
404	      await secrets.remove(secretId);
405	    }
406	    const actor = ctxActorInfo(ctx);
407	    await logActivity(db, {
408	      companyId: existing.companyId,
409	      actorType: actor.actorType,
410	      actorId: actor.actorId,
411	      agentId: actor.agentId,
412	      runId: actor.runId,
413	      action: "environment.deleted",
414	      entityType: "environment",
415	      entityId: removed.id,
416	      details: {
417	        name: removed.name,
418	        driver: removed.driver,
419	        status: removed.status,
420	      },
421	    });
422	    return Response.json(removed);
423	  };
424	
425	  const probeEnvironmentHandler: Handler = async (ctx) => {
426	    const id = ctx.param("id");
427	    if (!id) return Response.json({ error: "Missing id" }, { status: 400 });
428	    const environment = await svc.getById(id);
429	    if (!environment) {
430	      return Response.json({ error: "Environment not found" }, { status: 404 });
431	    }
432	    await assertCanMutateEnvironments(ctx, environment.companyId);
433	    const actor = ctxActorInfo(ctx);
434	    const probe = await probeEnvironment(db, environment, {
435	      pluginWorkerManager: options.pluginWorkerManager,
436	    });
437	    await logActivity(db, {
438	      companyId: environment.companyId,
439	      actorType: actor.actorType,
440	      actorId: actor.actorId,
441	      agentId: actor.agentId,
442	      runId: actor.runId,
443	      action: "environment.probed",
444	      entityType: "environment",
445	      entityId: environment.id,
446	      details: {
447	        driver: environment.driver,
448	        ok: probe.ok,
449	        summary: probe.summary,
450	      },
451	    });
452	    return Response.json(probe);
453	  };
454	
455	  const probeEnvironmentConfig: Handler = async (ctx) => {
456	    const companyId = ctx.param("companyId");
457	    if (!companyId) return Response.json({ error: "Missing companyId" }, { status: 400 });
458	    await assertCanMutateEnvironments(ctx, companyId);
459	    const actor = ctxActorInfo(ctx);
460	    const body = await ctx.json<Record<string, unknown>>();
461	    const normalizedConfig = await normalizeEnvironmentConfigForProbe({
462	      db,
463	      driver: body.driver as string,
464	      config: body.config,
465	      pluginWorkerManager: options.pluginWorkerManager,
466	    });
467	    const environment = {
468	      id: "unsaved",
469	      companyId,
470	      name: (typeof body.name === "string" ? body.name.trim() : "") || "Unsaved environment",
471	      description: (body.description as string | undefined) ?? null,
472	      driver: body.driver as string,
473	      status: "active" as const,
474	      config: normalizedConfig,
475	      metadata: (body.metadata as Record<string, unknown> | undefined) ?? null,
476	      createdAt: new Date(),
477	      updatedAt: new Date(),
478	    };
479	    const probe = await probeEnvironment(db, environment, {
480	      pluginWorkerManager: options.pluginWorkerManager,
481	      resolvedConfig: {
482	        driver: body.driver as string,
483	        config: normalizedConfig,
484	      } as ParsedEnvironmentConfig,
485	    });
486	    await logActivity(db, {
487	      companyId,
488	      actorType: actor.actorType,
489	      actorId: actor.actorId,
490	      agentId: actor.agentId,
491	      runId: actor.runId,
492	      action: "environment.probed_unsaved",
493	      entityType: "environment",
494	      entityId: "unsaved",
495	      details: {
496	        driver: environment.driver,
497	        ok: probe.ok,
498	        summary: probe.summary,
499	        configTopLevelKeyCount: Object.keys(environment.config).length,
500	      },
501	    });
502	    return Response.json(probe);
503	  };
504	
505	  // ---------------------------------------------------------------------------
506	  // Wire handlers via expressHandler
507	  // ---------------------------------------------------------------------------
508	
509	  const adapterDeps = { db, storage: storageSentinel };
510	
511	  router.get("/companies/:companyId/environments", expressHandler(listEnvironments, adapterDeps));
512	  router.get("/companies/:companyId/environments/capabilities", expressHandler(getEnvironmentCapabilitiesHandler, adapterDeps));
513	  router.post("/companies/:companyId/environments", validate(createEnvironmentSchema), expressHandler(createEnvironment, adapterDeps));
514	  router.get("/environments/:id", expressHandler(getEnvironment, adapterDeps));
515	  router.get("/environments/:id/leases", expressHandler(listEnvironmentLeases, adapterDeps));
516	  router.get("/environment-leases/:leaseId", expressHandler(getEnvironmentLease, adapterDeps));
517	  router.patch("/environments/:id", validate(updateEnvironmentSchema), expressHandler(updateEnvironment, adapterDeps));
518	  router.delete("/environments/:id", expressHandler(deleteEnvironment, adapterDeps));
519	  router.post("/environments/:id/probe", expressHandler(probeEnvironmentHandler, adapterDeps));
520	  router.post(
521	    "/companies/:companyId/environments/probe-config",
522	    validate(probeEnvironmentConfigSchema),
523	    expressHandler(probeEnvironmentConfig, adapterDeps),
524	  );
525	
526	  return router;
527	}
